fn is_ascii_digit(c: char) -> bool {
    // Check if the character is in the range of ASCII digits '0' to '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Check if every character in the string is an ASCII digit
    // The empty string is considered to have all characters as digits
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false; // Return false if any character is not a digit
        }
    }
    true // All characters are digits
}

fn main() {
    // Example usage
    let test_str1 = String::from("12345");
    let test_str2 = String::from("123a45");
    let test_str3 = String::from("");

    println!("Is '{}' all digits? {}", test_str1, all_digits(test_str1)); // true
    println!("Is '{}' all digits? {}", test_str2, all_digits(test_str2)); // false
    println!("Is '{}' all digits? {}", test_str3, all_digits(test_str3)); // true
}